\begin{tikzpicture}[font=\sffamily, scale=1]

    % Power supply / battery
    \draw[thick] (0,3.5) rectangle (1,4.5);
    \node at (0.5,4) {DC};
    \draw[thick] (-0.2,3.9) -- (-0.8,3.9);
    \draw[thick] (-0.5,3.6) -- (-0.5,4.2);
    \node at (-0.8,4.3) {$+$};
    \node at (-0.8,3.5) {$-$};

    % Wires from DC source
    \draw[thick] (-0.5,4.2) -- (-0.5,4.8) -- (1.5,4.8);
    \draw[thick] (-0.5,3.6) -- (-0.5,3.0) -- (4.5,3.0);

    % Beaker
    \draw[thick] (1,0) -- (1,2.8) arc (180:360:1.5) -- (4,0) -- cycle;

    % Electrolyte (dilute NaCl solution)
    \dotregion{1.01}{0.01}{3.99}{1.8}
    \node at (2.5,1.0) {\small Dilute $\text{NaCl(aq)}$};

    % Inverted test tube left (anode)
    \begin{scope}[shift={(1.5,0.8)}]
        \draw[thick] (0,0) rectangle (0.6,3.2);
        \draw[thick, white] (0,0) -- (0.6,0); % open bottom
        \draw[thick] (0,3.2) arc (180:0:0.3);
        % Gas collected at top
        \fill[white] (0.05,2.4) rectangle (0.55,3.15);
        \draw[dashed] (0.05,2.4) -- (0.55,2.4);
        \node at (0.3,2.8) {\small Gas X};
        % Carbon electrode inside
        \draw[thick, fill=gray!30] (0.2,0.5) rectangle (0.4,2.2);
    \end{scope}

    % Inverted test tube right (cathode)
    \begin{scope}[shift={(2.9,0.8)}]
        \draw[thick] (0,0) rectangle (0.6,3.2);
        \draw[thick, white] (0,0) -- (0.6,0); % open bottom
        \draw[thick] (0,3.2) arc (180:0:0.3);
        % Gas collected at top (larger volume)
        \fill[white] (0.05,1.6) rectangle (0.55,3.15);
        \draw[dashed] (0.05,1.6) -- (0.55,1.6);
        \node at (0.3,2.4) {\small Gas Y};
        % Carbon electrode inside
        \draw[thick, fill=gray!30] (0.2,0.5) rectangle (0.4,2.2);
    \end{scope}

    % Connecting wires to electrodes through test tubes
    \draw[thick] (1.5,4.8) -- (1.7,4.8) -- (1.7,3.0);
    \draw[thick] (1.7,3.0) -- (1.9,3.0); % to left electrode top

    \draw[thick] (4.5,3.0) -- (3.3,3.0); % to right electrode top

    % Labels for electrodes
    \node[above] at (1.7,3.0) {\small Anode};
    \node[above] at (3.3,3.0) {\small Cathode};

    % Caption
    \node at (2.5,-0.6) {Fig. 3.1};

\end{tikzpicture}

